with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);c=browser.new_context(viewport={'width':1440,'height':900});name,value=state['adminCookie'].split('=',1);c.add_cookies([{'name':name,'value':value,'url':base}]);page=c.new_page();page.on('dialog',lambda d:d.accept());page.goto(base);page.get_by_role('tab',name='短视频权限验收').click();page.get_by_role('button',name='内容池',exact=True).click();page.locator('.content-board-card .content-cover-button').first.click();dialog=page.get_by_role('dialog',name='内容详情',exact=True);expect(dialog).to_be_visible();dialog.locator('.unified-detail').evaluate("e=>{const spacer=document.createElement('div');spacer.style.height='1800px';spacer.textContent='长内容滚动测试';e.append(spacer)}");body=dialog.locator('.dialog-body');body.evaluate('(e)=>e.scrollTop=900');page.wait_for_timeout(100);back=dialog.locator('.back-square');expect(back).to_be_in_viewport();r=back.bounding_box();container=body.bounding_box();assert r['y']>=container['y']-1,(r,container);back.click();expect(dialog).to_have_count(0);browser.close();print(json.dumps({'checks':3,'dialogReturnStaysVisible':True,'dialogReturnWorks':True}))
